// Jarvis · codice completo (modulo). NON contiene segreti: URL e chiave
// arrivano dal piccolo script "Jarvis" sul telefono (il loader).
// Uso: const run = importModule(percorso); await run({ WEBHOOK_URL, WEBHOOK_AUTH, name: Script.name() });
module.exports = async function (cfg) {
cfg = cfg || {};
const WEBHOOK_URL = cfg.WEBHOOK_URL;
const WEBHOOK_AUTH = cfg.WEBHOOK_AUTH;
const SCRIPT_NAME = cfg.name || Script.name();

const TIMEOUT_SECONDS = 20;
const MAX_CHARS = 4000;

const IMG_SMALL = "";
const IMG_MEDIUM = "";

// ---------- configurazione ----------
function cleanValue(v) {
  return String(v || "").trim().replace(/^["'“”‘’]+|["'“”‘’]+$/g, "").trim();
}
function isPlaceholder(v) {
  const s = cleanValue(v);
  return s === "" || /INCOLLA_QUI/i.test(s);
}
function authHeaderValue() {
  let s = cleanValue(WEBHOOK_AUTH);
  // se ha incollato anche "Authorization:" davanti, lo togliamo
  s = s.replace(/^authorization\s*:\s*/i, "").trim();
  if (/^bearer\s+/i.test(s)) return "Bearer " + s.replace(/^bearer\s+/i, "").trim();
  // chiave "nuda" (senza spazi): aggiungiamo noi "Bearer "
  if (!/\s/.test(s)) return "Bearer " + s;
  return s; // altro schema (es. "Basic ...") lasciato com'è
}
function configProblem() {
  const url = cleanValue(WEBHOOK_URL);
  if (isPlaceholder(url) && isPlaceholder(WEBHOOK_AUTH))
    return "Manca la configurazione. Apri lo script Jarvis in Scriptable e incolla in alto il «Webhook URL» e l'«Authorization header» presi dal pannello della routine.";
  if (isPlaceholder(url))
    return "Manca il «Webhook URL». Apri lo script Jarvis e incollalo al posto di INCOLLA_QUI_URL.";
  if (!/^https:\/\//i.test(url))
    return "Il «Webhook URL» deve iniziare con https://. Ricopialo dal pannello della routine.";
  if (isPlaceholder(WEBHOOK_AUTH))
    return "Manca l'«Authorization header». Apri lo script Jarvis e incollalo al posto di INCOLLA_QUI_HEADER.";
  return null;
}

// ---------- invio ----------
async function sendMessage(text) {
  const problem = configProblem();
  if (problem) return { ok: false, title: "Configurazione mancante", msg: problem };

  const req = new Request(cleanValue(WEBHOOK_URL));
  req.method = "POST";
  req.timeoutInterval = TIMEOUT_SECONDS;
  req.headers = {
    "Authorization": authHeaderValue(),
    "Content-Type": "application/json",
    "Accept": "application/json",
  };
  req.body = JSON.stringify({ message: text, source: "jarvis-widget" });

  let body = "";
  try {
    body = await req.loadString();
  } catch (e) {
    const m = String(e && e.message ? e.message : e);
    console.error("Invio fallito: " + m);
    if (/timed out|scadut|timeout/i.test(m))
      return { ok: false, title: "Nessuna risposta", msg: "Il server non ha risposto in tempo. Controlla la connessione e riprova." };
    if (/offline|internet|network|connessione|rete|host|resolve/i.test(m))
      return { ok: false, title: "Niente internet", msg: "Sembra che il telefono non sia connesso. Controlla Wi‑Fi o dati cellulare e riprova." };
    return { ok: false, title: "Invio non riuscito", msg: "Errore di rete: " + m };
  }

  const code = (req.response && req.response.statusCode) || 0;
  console.log("HTTP " + code + " " + String(body).slice(0, 300));
  if (code >= 200 && code < 300) return { ok: true, code };

  let msg;
  if (code === 401 || code === 403)
    msg = "La chiave non è stata accettata. Ricopia l'«Authorization header» dal pannello della routine (tutto, compreso «Bearer»).";
  else if (code === 404)
    msg = "Indirizzo non trovato. Ricopia il «Webhook URL» dal pannello della routine.";
  else if (code === 413)
    msg = "Messaggio troppo lungo. Prova ad accorciarlo.";
  else if (code === 429)
    msg = "Troppi messaggi in poco tempo. Aspetta un minuto e riprova.";
  else if (code >= 500)
    msg = "Il server di Grok Bot ha un problema momentaneo. Riprova tra poco.";
  else
    msg = "Il server ha risposto in modo inatteso.";
  return { ok: false, title: "Errore " + code, msg };
}

// ---------- widget ----------
function img(b64) {
  try { return Image.fromData(Data.fromBase64String(b64)); } catch (e) { return null; }
}

function runURL() {
  // URL documentato: scriptable:///run/NomeScript (nome codificato)
  return "scriptable:///run/" + encodeURIComponent(SCRIPT_NAME);
}

function buildWidget(family) {
  const w = new ListWidget();
  const medium = family !== "small";
  const bg = img(medium ? IMG_MEDIUM : IMG_SMALL);
  if (bg) w.backgroundImage = bg;
  else w.backgroundColor = new Color("#0A1430");
  w.url = runURL();
  w.refreshAfterDate = new Date(Date.now() + 24 * 3600 * 1000); // è statico: niente refresh inutili

  const cyan = new Color("#7FE7FF");
  const white = new Color("#FFFFFF");
  const soft = new Color("#CFEFFF", 0.85);
  const shadow = new Color("#000000", 0.7);
  const ready = !configProblem();

  if (medium) {
    w.setPadding(14, 16, 14, 18);
    const row = w.addStack();
    row.layoutHorizontally();
    row.addSpacer(); // l'orb è nello sfondo a sinistra
    const col = row.addStack();
    col.layoutVertically();
    col.size = new Size(150, 0);
    col.addSpacer();
    const tag = col.addText("J.A.R.V.I.S.");
    tag.font = Font.semiboldMonospacedSystemFont(10); tag.textColor = cyan; tag.shadowColor = shadow; tag.shadowRadius = 3;
    col.addSpacer(2);
    const t = col.addText("DOBBY");
    t.font = Font.heavySystemFont(26); t.textColor = white; t.shadowColor = shadow; t.shadowRadius = 4;
    col.addSpacer(2);
    const s = col.addText("Tocca per parlarmi");
    s.font = Font.mediumSystemFont(13); s.textColor = soft; s.shadowColor = shadow; s.shadowRadius = 3;
    col.addSpacer(8);
    const st = col.addText(ready ? "● online" : "● da configurare");
    st.font = Font.semiboldMonospacedSystemFont(10);
    st.textColor = ready ? new Color("#5CFFB0") : new Color("#FFC15C");
    st.shadowColor = shadow; st.shadowRadius = 3;
    col.addSpacer();
  } else {
    w.setPadding(10, 12, 10, 12);
    w.addSpacer();
    const t = w.addText("DOBBY");
    t.font = Font.heavySystemFont(17); t.textColor = white; t.centerAlignText(); t.shadowColor = shadow; t.shadowRadius = 4;
    const s = w.addText(ready ? "Tocca per parlarmi" : "Da configurare");
    s.font = Font.mediumSystemFont(11); s.textColor = ready ? soft : new Color("#FFC15C"); s.centerAlignText(); s.shadowColor = shadow; s.shadowRadius = 3;
  }
  return w;
}

// ---------- schermata Jarvis (HTML) ----------
function buildHTML(problem) {
  return `<!DOCTYPE html>
<html lang="it"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover">
<style>
:root{--cyan:#6fe6ff;--blue:#2f8cff;--ink:#e9f8ff}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0;height:100%;background:#040a1c;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","Helvetica Neue",Arial,sans-serif;overflow:hidden}
.bg{position:fixed;inset:0;background:radial-gradient(120% 80% at 50% 30%,#0d2350 0%,#071330 45%,#030817 100%);overflow:hidden}
.blob{position:absolute;border-radius:50%;filter:blur(40px);opacity:.55;animation:drift 14s ease-in-out infinite alternate}
.b1{width:260px;height:260px;left:-60px;top:80px;background:#1b5cff}
.b2{width:220px;height:220px;right:-50px;top:300px;background:#00c8ff;animation-duration:17s;opacity:.35}
.b3{width:300px;height:300px;left:40px;bottom:-120px;background:#5a2cff;animation-duration:20s;opacity:.3}
@keyframes drift{from{transform:translate(0,0) scale(1)}to{transform:translate(40px,-30px) scale(1.15)}}
.wrap{position:relative;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:calc(env(safe-area-inset-top) + 56px) 18px calc(env(safe-area-inset-bottom) + 18px)}
.glass{width:100%;max-width:420px;border-radius:30px;padding:22px 18px 18px;background:linear-gradient(160deg,rgba(255,255,255,.14),rgba(255,255,255,.05));border:1px solid rgba(255,255,255,.18);box-shadow:0 20px 60px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,255,255,.25);-webkit-backdrop-filter:blur(22px) saturate(140%);backdrop-filter:blur(22px) saturate(140%)}
.head{text-align:center;margin-bottom:6px}
.tag{font:600 11px ui-monospace,Menlo,monospace;letter-spacing:.35em;color:var(--cyan);opacity:.9}
.name{font-size:30px;font-weight:800;letter-spacing:.12em;margin-top:4px;text-shadow:0 0 18px rgba(111,230,255,.55)}
.orbbox{display:flex;justify-content:center;margin:6px 0 8px}
svg#orb{width:min(72vw,280px);height:min(72vw,280px);overflow:visible}
.status{text-align:center;font:500 13px ui-monospace,Menlo,monospace;color:#a9dcff;min-height:18px;margin-bottom:12px;letter-spacing:.06em}
.status .dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#5cffb0;margin-right:7px;box-shadow:0 0 8px #5cffb0;vertical-align:1px}
.row{display:flex;gap:10px;align-items:flex-end}
textarea{flex:1;resize:none;height:84px;border-radius:18px;padding:12px 14px;font-size:17px;line-height:1.3;color:#fff;background:rgba(5,15,40,.45);border:1px solid rgba(111,230,255,.35);outline:none;-webkit-appearance:none;font-family:inherit}
textarea::placeholder{color:rgba(200,235,255,.5)}
textarea:focus{border-color:var(--cyan);box-shadow:0 0 0 3px rgba(111,230,255,.18)}
button#send{width:58px;height:58px;border-radius:50%;border:none;flex:none;background:radial-gradient(circle at 35% 30%,#9ff3ff,#2fb8ff 45%,#1f5cff);box-shadow:0 0 22px rgba(70,190,255,.65),inset 0 1px 0 rgba(255,255,255,.6);display:flex;align-items:center;justify-content:center;transition:transform .15s}
button#send:active{transform:scale(.92)}
button#send:disabled{opacity:.5}
button#send svg{width:26px;height:26px}
.hint{text-align:center;font-size:12px;color:rgba(200,235,255,.55);margin-top:10px}
.shake{animation:shake .4s}
@keyframes shake{20%,60%{transform:translateX(-6px)}40%,80%{transform:translateX(6px)}}
.banner{display:none;margin-bottom:12px;padding:12px 14px;border-radius:16px;font-size:14px;line-height:1.35;background:rgba(255,170,60,.16);border:1px solid rgba(255,190,90,.5);color:#ffe2b5}
.overlay{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;padding:24px;background:rgba(2,6,20,.35);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);opacity:0;pointer-events:none;transition:opacity .25s}
.overlay.show{opacity:1;pointer-events:auto}
.card{width:100%;max-width:360px;text-align:center;border-radius:26px;padding:26px 20px 18px;background:linear-gradient(160deg,rgba(255,255,255,.18),rgba(255,255,255,.06));border:1px solid rgba(255,255,255,.22);-webkit-backdrop-filter:blur(20px);backdrop-filter:blur(20px);transform:scale(.85);transition:transform .35s cubic-bezier(.2,1.4,.4,1)}
.overlay.show .card{transform:scale(1)}
.card h2{margin:12px 0 6px;font-size:24px}
.card p{margin:0 0 16px;font-size:15px;line-height:1.4;color:#d6efff}
.card button{width:100%;padding:14px;border-radius:16px;border:1px solid rgba(111,230,255,.45);background:rgba(111,230,255,.15);color:#fff;font-size:16px;font-weight:600}
.check{width:84px;height:84px}
.check circle{fill:none;stroke:#5cffb0;stroke-width:4;stroke-dasharray:240;stroke-dashoffset:240}
.check path{fill:none;stroke:#5cffb0;stroke-width:6;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:60;stroke-dashoffset:60}
.overlay.show.ok .check circle{animation:draw .5s ease-out forwards}
.overlay.show.ok .check path{animation:draw .35s .45s ease-out forwards}
@keyframes draw{to{stroke-dashoffset:0}}
.err-ico{width:84px;height:84px;border-radius:50%;margin:0 auto;display:flex;align-items:center;justify-content:center;font-size:44px;font-weight:800;color:#ffb35c;border:4px solid #ffb35c}
</style></head>
<body>
<div class="bg"><div class="blob b1"></div><div class="blob b2"></div><div class="blob b3"></div></div>
<div class="wrap">
 <div class="glass" id="panel">
  <div class="head"><div class="tag">J.A.R.V.I.S.</div><div class="name">DOBBY</div></div>
  <div class="orbbox"><svg id="orb" viewBox="-150 -150 300 300">
   <defs>
    <radialGradient id="core" cx=".5" cy=".5" r=".5">
     <stop offset="0" stop-color="#ffffff"/><stop offset=".25" stop-color="#bff6ff"/><stop offset=".6" stop-color="#2fc4ff" stop-opacity=".85"/><stop offset="1" stop-color="#1f5cff" stop-opacity="0"/>
    </radialGradient>
    <radialGradient id="halo"><stop offset="0" stop-color="#3fd0ff" stop-opacity=".45"/><stop offset="1" stop-color="#3fd0ff" stop-opacity="0"/></radialGradient>
    <filter id="glow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="2.2" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
   </defs>
   <circle r="145" fill="url(#halo)" id="haloC"/>
   <g filter="url(#glow)" stroke="#6fe6ff" fill="none">
    <g id="ticks"></g>
    <g id="r1"><circle r="128" stroke-opacity=".35" stroke-width="1"/><circle r="122" stroke-width="2" stroke-dasharray="2 6" stroke-opacity=".8"/></g>
    <g id="r2"><path d="M0,-108 A108,108 0 0 1 93.5,-54" stroke-width="5" stroke-linecap="round"/><path d="M93.5,54 A108,108 0 0 1 0,108" stroke-width="5" stroke-linecap="round" stroke-opacity=".7"/><path d="M-76.4,76.4 A108,108 0 0 1 -104.3,-28" stroke-width="3" stroke-linecap="round" stroke-opacity=".55"/></g>
    <g id="r3"><circle r="92" stroke-width="1.2" stroke-dasharray="40 10 4 10" stroke-opacity=".9"/></g>
    <g id="r4"><path d="M-74,0 A74,74 0 0 1 0,-74" stroke-width="7" stroke="#38b6ff" stroke-linecap="round"/><path d="M74,0 A74,74 0 0 1 0,74" stroke-width="7" stroke="#38b6ff" stroke-linecap="round"/><circle r="66" stroke-width="1" stroke-opacity=".6"/></g>
    <g id="r5"><circle r="52" stroke-width="1.5" stroke-dasharray="3 5"/></g>
    <g id="sweep"><path d="M0,0 L0,-128" stroke-width="1.5" stroke-opacity=".7"/></g>
    <line x1="-140" y1="0" x2="-132" y2="0" stroke-width="1.5"/><line x1="132" y1="0" x2="140" y2="0" stroke-width="1.5"/><line x1="0" y1="-140" x2="0" y2="-132" stroke-width="1.5"/><line x1="0" y1="132" x2="0" y2="140" stroke-width="1.5"/>
   </g>
   <circle id="coreGlow" r="46" fill="url(#core)"/>
   <circle id="coreDot" r="14" fill="#ffffff"/>
  </svg></div>
  <div class="status" id="status"><span class="dot"></span>In ascolto</div>
  <div class="banner" id="banner"></div>
  <div class="row">
   <textarea id="msg" placeholder="Scrivi a Dobby…" maxlength="${MAX_CHARS}" enterkeyhint="send"></textarea>
   <button id="send" aria-label="Invia"><svg viewBox="0 0 24 24"><path d="M3 11.5 20.5 3.5 13 21l-2.3-7.2z" fill="#fff"/><path d="M10.7 13.8 20.5 3.5" stroke="#1f5cff" stroke-width="1.6"/></svg></button>
  </div>
  <div class="hint">Puoi anche dettare: tocca il riquadro e poi il 🎙️ sulla tastiera</div>
 </div>
</div>
<div class="overlay" id="ov"><div class="card">
 <div id="ovIcon"></div><h2 id="ovTitle"></h2><p id="ovMsg"></p>
 <button id="ovBtn">Scrivi un altro messaggio</button>
</div></div>
<script>
(function(){
 var PROBLEM = ${JSON.stringify(problem || "")};
 var NS="http://www.w3.org/2000/svg";
 var ticks=document.getElementById("ticks");
 for(var i=0;i<72;i++){var a=i*5*Math.PI/180,long=i%6===0,r1=long?134:137,r2=142;
  var l=document.createElementNS(NS,"line");l.setAttribute("x1",(Math.sin(a)*r1).toFixed(2));l.setAttribute("y1",(-Math.cos(a)*r1).toFixed(2));
  l.setAttribute("x2",(Math.sin(a)*r2).toFixed(2));l.setAttribute("y2",(-Math.cos(a)*r2).toFixed(2));l.setAttribute("stroke-width",long?"2":"1");l.setAttribute("stroke-opacity",long?"1":".5");ticks.appendChild(l);}
 var parts=[["r1",6],["r2",-22],["r3",14],["r4",-40],["r5",60],["sweep",90],["ticks",-3]].map(function(p){return {el:document.getElementById(p[0]),v:p[1],a:0};});
 var coreGlow=document.getElementById("coreGlow"),coreDot=document.getElementById("coreDot"),halo=document.getElementById("haloC");
 var speed=1,target=1,t=0,last=performance.now();
 window.__jarvisFrames=0;
 function frame(now){var dt=Math.min(.05,(now-last)/1000);last=now;speed+=(target-speed)*Math.min(1,dt*3);t+=dt*speed;
  for(var i=0;i<parts.length;i++){var p=parts[i];p.a=(p.a+p.v*dt*speed)%360;p.el.setAttribute("transform","rotate("+p.a.toFixed(2)+")");}
  var pulse=(Math.sin(t*Math.PI*1.4)+1)/2; // t scorre più veloce mentre invia → battito più rapido
  coreGlow.setAttribute("r",(40+pulse*12).toFixed(2));coreDot.setAttribute("r",(11+pulse*5).toFixed(2));
  halo.setAttribute("opacity",(.55+pulse*.45).toFixed(3));
  window.__jarvisFrames++;requestAnimationFrame(frame);}
 requestAnimationFrame(frame);

 var msg=document.getElementById("msg"),send=document.getElementById("send"),status=document.getElementById("status");
 var ov=document.getElementById("ov"),ovIcon=document.getElementById("ovIcon"),ovTitle=document.getElementById("ovTitle"),ovMsg=document.getElementById("ovMsg"),ovBtn=document.getElementById("ovBtn");
 var banner=document.getElementById("banner");
 if(PROBLEM){banner.textContent="⚠️ "+PROBLEM;banner.style.display="block";}
 function setStatus(txt,dot){status.innerHTML=(dot?'<span class="dot" style="background:'+dot+';box-shadow:0 0 8px '+dot+'"></span>':"")+txt;}

 // ---- ponte con Scriptable: il tasto Invia apre un indirizzo jarvis:// che Scriptable intercetta ----
 function deliver(payload){window.location.href="jarvis://send?t="+encodeURIComponent(payload.text);}

 function doSend(){if(sending)return;var text=msg.value.trim();
  if(!text){var row=msg.parentNode;row.classList.remove("shake");void row.offsetWidth;row.classList.add("shake");msg.focus();return;}
  sending=true;send.disabled=true;msg.blur();target=3.6;setStatus("Invio in corso…","#6fe6ff");
  deliver({type:"send",text:text});}
 send.addEventListener("click",doSend);
 msg.addEventListener("keydown",function(e){if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();doSend();}});

 window.__jarvisResult=function(r){sending=false;send.disabled=false;target=1;
  if(r&&r.ok){msg.value="";ov.className="overlay ok";
   ovIcon.innerHTML='<svg class="check" viewBox="0 0 84 84"><circle cx="42" cy="42" r="38"/><path d="M25 43 l11 11 l23 -24"/></svg>';
   ovTitle.textContent="Inviato ✓";ovMsg.textContent="Dobby ha ricevuto il tuo messaggio.";ovBtn.textContent="Scrivi un altro messaggio";
   setStatus("Messaggio consegnato","#5cffb0");}
  else{ov.className="overlay err";ovIcon.innerHTML='<div class="err-ico">!</div>';
   ovTitle.textContent=(r&&r.title)||"Invio non riuscito";ovMsg.textContent=(r&&r.msg)||"Riprova tra poco.";ovBtn.textContent="Ok, riprovo";
   setStatus("Messaggio non inviato","#ffb35c");}
  requestAnimationFrame(function(){ov.classList.add("show");});
  return true;};
 ovBtn.addEventListener("click",function(){ov.classList.remove("show");setStatus("In ascolto","#5cffb0");});
})();
</script></body></html>`;
}

async function runApp() {
  const wv = new WebView();
  let busy = false;
  async function handle(text) {
    text = String(text || "").trim().slice(0, MAX_CHARS);
    const result = text ? await sendMessage(text)
                        : { ok: false, title: "Messaggio vuoto", msg: "Scrivi qualcosa prima di inviare." };
    try { await wv.evaluateJavaScript("window.__jarvisResult(" + JSON.stringify(result) + ")"); }
    catch (e) { console.error("Risultato non mostrato: " + e); }
    busy = false;
  }
  wv.shouldAllowRequest = (req) => {
    const u = String((req && req.url) || "");
    if (!/^jarvis:/i.test(u)) return true;
    if (!busy) {
      busy = true;
      let text = "";
      try { const m = u.match(/[?&]t=([^&]*)/); text = m ? decodeURIComponent(m[1]) : ""; } catch (e) {}
      handle(text);
    }
    return false;
  };
  // prima mostra la finestra, poi carica la pagina (evita la schermata bianca)
  const shown = wv.present(true);
  await new Promise(r => Timer.schedule(250, false, r));
  await wv.loadHTML(buildHTML(configProblem()));
  await shown;
}

// ---------- avvio ----------
if (config.runsInWidget) {
  Script.setWidget(buildWidget(config.widgetFamily));
} else if (args.queryParameters && args.queryParameters.anteprima) {
  // scriptable:///run/Jarvis?anteprima=1  → mostra l'anteprima del widget
  await buildWidget("medium").presentMedium();
} else {
  await runApp();
}
Script.complete();
};
